// Uniforms: rotation speed, wave amplitude, hue offset
uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float waves : 0.5 .. 8.0 = 3.0;
uniform float hueOffset : 0.0 .. 1.0 = 0.0;

// State: phases for rotation and vertical wave
state fixed phRot;
state fixed phWave;

// Update: advance phases per uniform rate
void update() {
  // Wrap each rate with fract to avoid time jumps
  phRot = fract(phRot + fixed(dt * speed * 0.25));
  phWave = fract(phWave + fixed(dt * speed * 0.17));
}

// Per-LED shade: compute angle from cylinder axis, apply wave and rotate
vec3 shade(Led led) {
  // Fixed-point inputs
  fixed x = fixed(led.pos.x);
  fixed y = fixed(led.pos.y);
  fixed z = fixed(led.pos.z);

  // Angle around cylinder axis (in turns) using fixed atan2 (integer LUT)
  fixed ang = atan2(z, x) + fixed(0.5);   // shift to 0..1

  // Vertical wave displacement (using led.uv.y normalized to 0..1)
  fixed w = sin(fixed(led.uv.y) * fixed(waves) + phWave) * fixed(0.125);

  // Combined hue with rotation and wave, then HSV to RGB (fixed path)
  fixed h = fract(ang + phRot + w) + fixed(hueOffset);
  return hsv2rgb(h, fixed(0.9), fixed(1.0));
}
